<?php declare(strict_types=1);namespace NpmGateway\Tests\Unit;use NpmGateway\Notifications\{GatewayEmailRenderer,MarketingFlyerEmailSender};use PHPMailer\PHPMailer\PHPMailer;use PHPUnit\Framework\TestCase;
final class MarketingFlyerEmailSenderTest extends TestCase{
 private function config(bool$test=false,string$email=''):array{return['test_mode'=>$test,'test_email'=>$email,'app_url'=>'https://gateway.example.test','smtp'=>['host'=>'smtp.example.test','port'=>587,'username'=>'fake-user','password'=>'fake-password','secure'=>'tls','from_address'=>'no-reply@npmpropertiesinc.com','from_name'=>'NPM Gateway','recipients'=>'unused@example.test','environment'=>'testing']];}
 private function flyer():array{return['flyer_month'=>'2026-08-01','flyer_type'=>'standard','property_name'=>'Pine Hill','property_slug'=>'pine-hill','uploaded_by_name'=>'Kiyana Director','updated_at'=>'2026-08-09 22:08:29','public_id'=>str_repeat('F',26),'mime_type'=>'image/png'];}
 public function testProductionUsesManagerDownloadRouteAndNoAttachment():void{$mails=[];$sender=new MarketingFlyerEmailSender($this->config(),function()use(&$mails):PHPMailer{$mail=new MarketingFlyerCapturingPhpMailer();$mails[]=$mail;return$mail;},new GatewayEmailRenderer());$result=$sender->send($this->flyer(),['manager@example.test','assistant@example.test','manager@example.test']);self::assertSame(2,$result['sent']);foreach($mails as$mail){self::assertSame('August 2026 Flyer — Pine Hill',$mail->Subject);$url='https://gateway.example.test/community-actions/pine-hill/flyers/'.str_repeat('F',26).'/download';foreach([$mail->Body,$mail->AltBody]as$body){self::assertStringContainsString('Download Flyer',$body);self::assertStringContainsString($url,$body);self::assertStringNotContainsString('View / Download Flyer',$body);}self::assertSame(1,substr_count($mail->AltBody,$url));self::assertSame([],$mail->getAttachments());self::assertStringNotContainsString('Attached',$mail->Body);self::assertStringNotContainsString('fake-password',$mail->Body);}}
 public function testTestModeUsesCorporateDownloadRouteAndOnlyTestRecipient():void{$mails=[];$sender=new MarketingFlyerEmailSender($this->config(true,'flyer-test@example.test'),function()use(&$mails):PHPMailer{$mail=new MarketingFlyerCapturingPhpMailer();$mails[]=$mail;return$mail;});self::assertSame(1,$sender->send($this->flyer(),['real-manager@example.test'])['sent']);self::assertSame('flyer-test@example.test',$mails[0]->getToAddresses()[0][0]);self::assertStringContainsString('/corporate/marketing/flyers/'.str_repeat('F',26).'/download',$mails[0]->Body);self::assertStringContainsString('Download Flyer',$mails[0]->AltBody);self::assertSame([],$mails[0]->getAttachments());$closed=new MarketingFlyerEmailSender($this->config(true,''));self::assertSame(0,$closed->send($this->flyer(),['manager@example.test'])['sent']);}
}
final class MarketingFlyerCapturingPhpMailer extends PHPMailer{public function smtpConnect($options=null):bool{return true;}public function smtpClose():void{}public function postSend():bool{return true;}}
